 <div class="overlay" id="intro"><div class="dialog"><div class="eyebrow">A new chapter begins</div><h1>The Blazing Blade<span>Ashes at the Ford</span></h1><p>On the road through the plains, Lyn's company finds a caravan under attack. The bandit chief has blocked the crossing. Steel your resolve—and make every move count.</p><button class="action-btn primary" id="beginBtn">Begin chapter</button><div class="tip">A turn-based tactical adventure · defeat the chief to win</div></div></div>
 <div class="overlay hidden" id="result"><div class="dialog"><div class="eyebrow" id="resultEyebrow">Victory</div><h1 id="resultTitle">The ford is safe<span>Chapter complete</span></h1><p id="resultText"></p><button class="action-btn primary" id="restartBtn">Play again</button></div></div>
 <div class="forecast hidden" id="forecast"><div class="forecast-box"><div class="forecast-head"><span>Combat forecast</span><span id="weaponAdv">—</span></div><div class="forecast-units" id="forecastUnits"></div><div class="forecast-buttons"><button class="action-btn" id="cancelAttack">Cancel</button><button class="action-btn primary" id="confirmAttack">Fight</button></div></div></div>
 <script>
+const canvas=document.getElementById('map'),ctx=canvas.getContext('2d');
+const W=12,H=9,T=58;
+const terrain=[
+'ppppwppppppp','ppffwppffppp','pppfwppfpppp','ppppwppppppp','ppppbppppppp','ppppbppppppp','ppppwppppppp','ppffwppppfpp','ppppwppppppp'
+];
+const initialUnits=[
+{id:'lyn',name:'Lyn',class:'Swordmaster-in-training',side:'ally',x:1,y:4,hp:22,maxHp:22,str:6,skl:8,spd:9,def:3,move:5,weapon:'Iron sword',type:'sword',might:5,accuracy:90,range:1,color:'#53a4d3',hair:'#4b3029',skin:'#e3ae83',abbr:'L'},
+{id:'florina',name:'Florina',class:'Pegasus knight',side:'ally',x:2,y:3,hp:18,maxHp:18,str:5,skl:7,spd:8,def:4,move:6,weapon:'Iron lance',type:'lance',might:6,accuracy:80,range:1,color:'#a584d2',hair:'#d8b8b2',skin:'#f0c5a5',abbr:'F',fly:true},
+{id:'sain',name:'Sain',class:'Cavalier',side:'ally',x:1,y:5,hp:24,maxHp:24,str:7,skl:5,spd:6,def:6,move:6,weapon:'Iron lance',type:'lance',might:6,accuracy:80,range:1,color:'#6eaa7a',hair:'#be7a3d',skin:'#e8b58c',abbr:'S'},
+{id:'kent',name:'Kent',class:'Cavalier',side:'ally',x:0,y:4,hp:23,maxHp:23,str:6,skl:7,spd:7,def:7,move:6,weapon:'Iron sword',type:'sword',might:5,accuracy:90,range:1,color:'#bd665b',hair:'#b84d38',skin:'#e9b18b',abbr:'K'},
+{id:'ruffian1',name:'Mugger',class:'Bandit',side:'foe',x:8,y:2,hp:20,maxHp:20,str:6,skl:4,spd:4,def:2,move:4,weapon:'Iron axe',type:'axe',might:7,accuracy:70,range:1,color:'#ca6858',hair:'#573e31',skin:'#bd8665',abbr:'B'},
+{id:'ruffian2',name:'Raider',class:'Bandit',side:'foe',x:8,y:6,hp:21,maxHp:21,str:7,skl:3,spd:4,def:3,move:4,weapon:'Iron axe',type:'axe',might:7,accuracy:70,range:1,color:'#ca6858',hair:'#49382e',skin:'#bc8060',abbr:'B'},
+{id:'archer',name:'Lookout',class:'Archer',side:'foe',x:10,y:4,hp:18,maxHp:18,str:5,skl:6,spd:5,def:2,move:4,weapon:'Iron bow',type:'bow',might:5,accuracy:85,range:2,color:'#cb765d',hair:'#514131',skin:'#d09a72',abbr:'A'},
+{id:'grozny',name:'Grozny',class:'Bandit chief',side:'foe',x:10,y:2,hp:27,maxHp:27,str:8,skl:5,spd:4,def:5,move:4,weapon:'Steel axe',type:'axe',might:8,accuracy:70,range:1,color:'#dc6750',hair:'#483127',skin:'#b77e5e',abbr:'G',boss:true}
+];
+let units=[],selected=null,moveTiles=new Map(),attackMode=false,phase='player',turn=1,logLines=[],started=false,muted=false,cursor={x:1,y:4};
+const $=id=>document.getElementById(id), alive=u=>u&&u.hp>0, allies=()=>units.filter(u=>u.side==='ally'&&alive(u)), foes=()=>units.filter(u=>u.side==='foe'&&alive(u));
+function copyUnits(){units=initialUnits.map(u=>({...u,done:false,moved:false}));}
+function addLog(text,cls=''){logLines.unshift({text,cls});logLines=logLines.slice(0,9);$('log').innerHTML=logLines.map(l=>`<p class="${l.cls}">${l.text}</p>`).join('');}
+function tile(x,y){return terrain[y]?.[x]||'p'}
+function inBounds(x,y){return x>=0&&y>=0&&x<W&&y<H}
+function unitAt(x,y){return units.find(u=>alive(u)&&u.x===x&&u.y===y)}
+function terrainCost(u,x,y){const t=tile(x,y);if(t==='w')return u.fly?1:Infinity;if(t==='f')return u.fly?1:2;if(t==='m')return u.fly?1:Infinity;return 1}
+function distance(a,b){return Math.abs(a.x-b.x)+Math.abs(a.y-b.y)}
+function moveMap(u){const dist=new Map([[`${u.x},${u.y}`,0]]),prev=new Map(),q=[{x:u.x,y:u.y,c:0}];while(q.length){q.sort((a,b)=>a.c-b.c);const cur=q.shift(),key=`${cur.x},${cur.y}`;if(cur.c!==dist.get(key))continue;for(const [dx,dy]of [[1,0],[-1,0],[0,1],[0,-1]]){const x=cur.x+dx,y=cur.y+dy;if(!inBounds(x,y))continue;const occ=unitAt(x,y);if(occ&&occ!==u)continue;const cost=terrainCost(u,x,y),nc=cur.c+cost,k=`${x},${y}`;if(cost!==Infinity&&nc<=u.move&&(dist.get(k)===undefined||nc<dist.get(k))){dist.set(k,nc);prev.set(k,key);q.push({x,y,c:nc})}}}return{dist,prev}}
+function canAttack(a,b){return alive(a)&&alive(b)&&distance(a,b)>=a.rangeMin&&distance(a,b)<=a.range}
+function triangle(a,b){const beats={sword:'axe',axe:'lance',lance:'sword'};return beats[a.type]===b.type?1:beats[b.type]===a.type?-1:0}
+function terrainBonus(u){return tile(u.x,u.y)==='f'?1:tile(u.x,u.y)==='h'?2:0}
+function combatStats(a,b){const adv=triangle(a,b),dmg=Math.max(0,a.str+a.might+adv*2-b.def-terrainBonus(b)),hit=Math.max(25,Math.min(100,a.accuracy+a.skl*2+adv*15-b.spd*2-terrainBonus(b)*10)),count=a.spd-b.spd>=4?2:1;return{dmg,hit,count,adv}}
+function allowedAttackTargets(u){return foes().filter(e=>canAttack(u,e))}
+function drawTile(x,y){const t=tile(x,y),px=x*T,py=y*T;let base=t==='w'?'#477b87':t==='b'?'#b89964':t==='f'?'#58794f':t==='h'?'#9d8760':'#8b9b70';ctx.fillStyle=base;ctx.fillRect(px,py,T,T);
+// hand-painted tile texture
+ctx.globalAlpha=.16;for(let i=0;i<5;i++){const xx=px+(i*19+x*11+y*7)%T, yy=py+(i*27+y*13+x*3)%T;ctx.fillStyle=(i%2?'#f0d7a0':'#263e3a');ctx.fillRect(xx,yy,2+(i%3),2)}ctx.globalAlpha=1;
+if(t==='w'){ctx.strokeStyle='#a1c9c4';ctx.globalAlpha=.35;for(let i=0;i<3;i++){ctx.beginPath();ctx.moveTo(px+6,py+13+i*16);ctx.quadraticCurveTo(px+28,py+5+i*16,px+52,py+13+i*16);ctx.stroke()}ctx.globalAlpha=1}
+if(t==='b'){ctx.fillStyle='#594a36';for(let i=3;i<58;i+=11)ctx.fillRect(px+i,py+2,2,54);ctx.strokeStyle='#dbbd85';ctx.lineWidth=2;ctx.strokeRect(px+2,py+3,54,52);ctx.lineWidth=1}
+if(t==='f'){ctx.fillStyle='#344f3c';for(const [ox,oy,r]of [[13,18,9],[31,12,10],[44,26,10],[20,38,10],[39,44,9]]){ctx.beginPath();ctx.arc(px+ox,py+oy,r,0,Math.PI*2);ctx.fill();ctx.fillStyle='#7d9a61';ctx.beginPath();ctx.arc(px+ox-2,py+oy-3,r*.48,0,Math.PI*2);ctx.fill();ctx.fillStyle='#344f3c'}}
+if(t==='h'){ctx.fillStyle='#6c563f';ctx.fillRect(px+10,py+12,38,35);ctx.fillStyle='#c1a56e';ctx.fillRect(px+6,py+9,46,6);ctx.fillStyle='#433f35';ctx.fillRect(px+24,py+28,10,19)}
+ctx.strokeStyle='#344a43';ctx.globalAlpha=.32;ctx.strokeRect(px+.5,py+.5,T-1,T-1);ctx.globalAlpha=1;
+}
+function drawUnit(u){const x=u.x*T,y=u.y*T, cx=x+T/2,cy=y+T/2;ctx.save();if(u.done&&u.side==='ally')ctx.globalAlpha=.52;
+// shadow and unit token
+ctx.fillStyle='#14202b';ctx.beginPath();ctx.ellipse(cx,cy+13,17,7,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=u.color;ctx.beginPath();ctx.arc(cx,cy,17,0,Math.PI*2);ctx.fill();ctx.strokeStyle=u.boss?'#ffd477':'#f1dfb8';ctx.lineWidth=u.boss?2.5:1.5;ctx.stroke();
+// miniature face/hood
+ctx.fillStyle=u.hair;ctx.beginPath();ctx.arc(cx,cy-4,9,Math.PI,0);ctx.fill();ctx.fillRect(cx-9,cy-4,18,7);ctx.fillStyle=u.skin;ctx.fillRect(cx-6,cy-4,12,12);ctx.fillStyle='#26303a';ctx.fillRect(cx-4,cy,2,2);ctx.fillRect(cx+3,cy,2,2);
+// tiny class mark
+ctx.fillStyle='#fff0c8';ctx.font='bold 8px Arial';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(u.abbr,cx,cy+12);ctx.restore();
+// hp pips
+const barW=32;ctx.fillStyle='#18232a';ctx.fillRect(cx-barW/2, y+T-5,barW,3);ctx.fillStyle=u.hp/u.maxHp>.5?'#b5d294':'#e18470';ctx.fillRect(cx-barW/2,y+T-5,barW*u.hp/u.maxHp,3);
+if(selected===u){ctx.strokeStyle='#ffe18a';ctx.lineWidth=2;ctx.strokeRect(x+2,y+2,T-4,T-4)}
+if(u.boss){ctx.fillStyle='#ffe18a';ctx.font='12px serif';ctx.textAlign='center';ctx.fillText('✦',cx,y+8)}
+}
+function draw(){ctx.clearRect(0,0,canvas.width,canvas.height);for(let y=0;y<H;y++)for(let x=0;x<W;x++)drawTile(x,y);
+// objective seal
+ctx.fillStyle='#e7c56e';ctx.globalAlpha=.4;ctx.beginPath();ctx.arc(10*T+29,3*T+29,22,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.strokeStyle='#ffe39a';ctx.setLineDash([3,3]);ctx.beginPath();ctx.arc(10*T+29,3*T+29,20,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);
+if(selected&&phase==='player'&&!selected.done){for(const key of moveTiles.keys()){const [x,y]=key.split(',').map(Number);ctx.fillStyle='rgba(104,177,218,.35)';ctx.fillRect(x*T+2,y*T+2,T-4,T-4);ctx.strokeStyle='#9bd3f0';ctx.strokeRect(x*T+2,y*T+2,T-4,T-4)} }
+if(attackMode&&selected){for(const e of foes()){if(canAttack(selected,e)){ctx.fillStyle='rgba(219,90,74,.35)';ctx.fillRect(e.x*T+2,e.y*T+2,T-4,T-4)}}}
+units.filter(alive).forEach(drawUnit);
+if(cursor){ctx.strokeStyle='#fff2c2';ctx.globalAlpha=.75;ctx.lineWidth=1;ctx.strokeRect(cursor.x*T+4,cursor.y*T+4,T-8,T-8);ctx.globalAlpha=1}
+}

