function portrait(u){const c=document.createElement('canvas');c.width=60;c.height=64;const g=c.getContext('2d');g.fillStyle='#243b4c';g.fillRect(0,0,60,64);g.fillStyle='#314d5b';g.fillRect(0,0,60,22);g.fillStyle=u.color;g.globalAlpha=.45;g.fillRect(4,4,52,56);g.globalAlpha=1;g.fillStyle=u.hair;g.beginPath();g.ellipse(31,28,17,21,0,0,Math.PI*2);g.fill();g.fillStyle=u.skin;g.beginPath();g.ellipse(31,30,12,16,0,0,Math.PI*2);g.fill();g.fillStyle=u.hair;g.beginPath();g.moveTo(15,26);g.lineTo(17,7);g.lineTo(36,8);g.lineTo(47,20);g.lineTo(38,18);g.lineTo(30,25);g.lineTo(22,20);g.closePath();g.fill();g.fillStyle='#27313b';g.fillRect(24,28,3,2);g.fillRect(36,28,3,2);g.strokeStyle='#8c5144';g.beginPath();g.moveTo(28,38);g.lineTo(34,39);g.stroke();g.fillStyle='#e3c881';g.fillRect(0,52,60,12);g.fillStyle='#263545';g.font='bold 8px Arial';g.textAlign='center';g.fillText(u.class.toUpperCase(),30,60);return c}
function renderPanel(){const u=selected||null,box=$('unitPanel');if(!u){box.innerHTML='<div style="padding:16px 3px;color:#aab6c0;font:11px/1.5 Arial,sans-serif">Select one of Lyn’s company to see their battle details.</div>';$('unitState').textContent='—';}else{const state=u.done?'Spent':u.moved?'Moved · ready':'Ready';$('unitState').textContent=state;box.innerHTML=`<div class="unit-top"><div class="portrait"></div><div><div class="unit-name">${u.name}${u.boss?' ✦':''}</div><div class="unit-class">${u.class}</div></div></div><div class="hp-row"><span>HP</span><span>${u.hp} / ${u.maxHp}</span></div><div class="hp-track"><div class="hp-fill" style="width:${100*u.hp/u.maxHp}%"></div></div><div class="stats"><div class="stat"><b>${u.str}</b><span>STR</span></div><div class="stat"><b>${u.skl}</b><span>SKL</span></div><div class="stat"><b>${u.spd}</b><span>SPD</span></div><div class="stat"><b>${u.def}</b><span>DEF</span></div></div><div class="weapon-row"><span>Weapon</span><b>${u.weapon}</b><span>Move ${u.move}</span></div>`;box.querySelector('.portrait').appendChild(portrait(u))}
const left=allies().filter(a=>!a.done).length;$('orderCount').textContent=phase==='player'?`${left} ready`:'Enemy turn';$('turnLabel').textContent=`Turn ${turn}`;$('phaseLabel').textContent=phase==='player'?'Your phase':'Bandit phase';$('phaseDot').style.background=phase==='player'?'#72b1d6':'#dc7763';$('endTurn').disabled=phase!=='player';$('endTurn').innerHTML=phase==='player'?'End phase <span> ↵</span>':'Bandits act…';
let prompt='Select a unit to view its movement range.';if(phase!=='player')prompt='The bandits are moving.';else if(selected){if(selected.done)prompt=`${selected.name} has finished their orders.`;else if(selected.moved)prompt=`${selected.name} moved. Attack a nearby foe or wait.`;else prompt=`${selected.name} can move ${selected.move} spaces, then act.`;if(attackMode)prompt='Choose a highlighted enemy to preview an attack.'} $('prompt').textContent=prompt;
$('attackBtn').disabled=phase!=='player'||!selected||selected.done||!foes().some(e=>canAttack(selected,e));$('waitBtn').disabled=phase!=='player'||!selected||selected.done;
}
function selectUnit(u){selected=u;attackMode=false;moveTiles=new Map();if(u&&phase==='player'&&!u.done&&!u.moved)moveTiles=moveMap(u).dist;cursor=u?{x:u.x,y:u.y}:cursor;renderPanel();draw()}
function tileFromEvent(e){const r=canvas.getBoundingClientRect();return{x:Math.floor((e.clientX-r.left)*W/r.width),y:Math.floor((e.clientY-r.top)*H/r.height)}}
function pathTo(u,x,y){const {prev}=moveMap(u);let k=`${x},${y}`,path=[];while(k!==`${u.x},${u.y}`){const [px,py]=k.split(',').map(Number);path.unshift({x:px,y:py});k=prev.get(k);if(!k)return[]}return path}
function moveUnit(u,x,y){if(u.moved||u.done)return;const path=pathTo(u,x,y);if(!path.length)return;u.x=x;u.y=y;u.moved=true;cursor={x,y};addLog(`${u.name} advances to the ford.`);renderPanel();draw()}
function handleMapClick(e){if(!started||phase!=='player'||$('forecast').classList.contains('hidden')===false)return;const {x,y}=tileFromEvent(e);if(!inBounds(x,y))return;cursor={x,y};const u=unitAt(x,y);
if(attackMode&&selected){if(u&&u.side==='foe'&&canAttack(selected,u)){showForecast(selected,u);return}if(u&&u.side==='ally'){selectUnit(u);return}return}
if(u){if(u.side==='ally'){selectUnit(u);return}if(selected&&canAttack(selected,u)){showForecast(selected,u);return}if(selected&&selected.moved){$('prompt').textContent='That foe is out of range. Choose a nearby target or wait.'}draw();return}
if(selected&&!selected.done&&!selected.moved&&moveTiles.has(`${x},${y}`)){moveUnit(selected,x,y);return}draw()}
function showForecast(a,b){const s1=combatStats(a,b),canCounter=canAttack(b,a),s2=canCounter?combatStats(b,a):null;$('weaponAdv').textContent=s1.adv>0?'Weapon advantage':s1.adv<0?'Weapon disadvantage':'Even match';$('forecastUnits').innerHTML=`<div class="forecast-unit"><h3>${a.name}</h3><div class="damage">${s1.dmg} × ${s1.count}</div><p>Hit ${s1.hit}% · HP ${a.hp}</p></div><div class="forecast-unit"><h3>${b.name}</h3><div class="damage">${canCounter?s2.dmg+' × '+s2.count:'—'}</div><p>${canCounter?'Hit '+s2.hit+'% · HP '+b.hp:'Cannot counter'}</p></div>`;$('forecast').classList.remove('hidden');$('confirmAttack').onclick=()=>{$('forecast').classList.add('hidden');resolveCombat(a,b)};$('cancelAttack').onclick=()=>$('forecast').classList.add('hidden')}
function resolveCombat(a,b){if(!alive(a)||!alive(b))return;const first=combatStats(a,b);addLog(`${a.name} attacks ${b.name}!`,'gold');let killed=false;for(let i=0;i<first.count;i++){if(!alive(b))break;if(Math.random()*100<first.hit){b.hp=Math.max(0,b.hp-first.dmg);addLog(`${a.name} hits for ${first.dmg} damage.`);if(!b.hp){addLog(`${b.name} is defeated!`,'red');killed=true;break}}else addLog(`${a.name} misses.`)}if(!killed&&alive(b)&&canAttack(b,a)){const counter=combatStats(b,a);if(Math.random()*100<counter.hit){a.hp=Math.max(0,a.hp-counter.dmg);addLog(`${b.name} counters for ${counter.dmg} damage.`);if(!a.hp){addLog(`${a.name} falls in battle.`,'red');if(a.boss){} }}else addLog(`${b.name} misses the counter.`)}a.done=true;selected=null;attackMode=false;moveTiles.clear();renderPanel();draw();checkResult()}
function waitUnit(){if(!selected||selected.done)return;addLog(`${selected.name} waits.`);selected.done=true;selected=null;attackMode=false;moveTiles.clear();renderPanel();draw();if(allies().every(a=>a.done))setTimeout(enemyPhase,450)}
function endPlayerPhase(){if(phase!=='player')return;selected=null;attackMode=false;moveTiles.clear();phase='enemy';renderPanel();draw();setTimeout(enemyPhase,500)}
function enemyPhase(){if(phase!=='enemy'||!started)return;const order=foes().slice();let i=0;function act(){if(i>=order.length||phase!=='enemy'){finishEnemyPhase();return}const e=order[i++];if(!alive(e)){setTimeout(act,120);return}const targets=allies();if(!targets.length){checkResult();return}let target=targets.slice().sort((a,b)=>distance(e,a)-distance(e,b))[0];if(canAttack(e,target)){resolveEnemyAttack(e,target);setTimeout(act,420);return}const {dist}=moveMap(e);let options=[];for(const [key,cost]of dist){if(cost===0)continue;const [x,y]=key.split(',').map(Number);const d=Math.min(...targets.map(t=>Math.max(0,distance({x,y},t)-e.range)));options.push({x,y,cost,d})}options.sort((a,b)=>a.d-b.d||a.cost-b.cost);if(options[0]&&options[0].d<Math.max(0,distance(e,target)-e.range)){e.x=options[0].x;e.y=options[0].y;addLog(`${e.name} advances.`);target=allies().slice().sort((a,b)=>distance(e,a)-distance(e,b))[0];draw();renderPanel()}if(target&&canAttack(e,target))resolveEnemyAttack(e,target);setTimeout(act,520)}act()}
function resolveEnemyAttack(a,b){const c=combatStats(a,b);addLog(`${a.name} strikes at ${b.name}.`,'red');if(Math.random()*100<c.hit){b.hp=Math.max(0,b.hp-c.dmg);addLog(`${b.name} takes ${c.dmg} damage.`);if(!b.hp)addLog(`${b.name} is down!`,'red')}else addLog(`${b.name} evades the blow.`);draw();renderPanel();checkResult()}
function finishEnemyPhase(){if(phase!=='enemy')return;if(checkResult())return;phase='player';turn++;units.filter(u=>u.side==='ally'&&alive(u)).forEach(u=>{u.done=false;u.moved=false});selected=null;renderPanel();draw();addLog(`Turn ${turn}. Lyn's company is ready.`,'gold')}
function checkResult(){if(!allies().length){showResult(false);return true}if(!foes().length){showResult(true);return true}return false}
function showResult(win){phase='result';selected=null;$('resultEyebrow').textContent=win?'Victory':'Defeat';$('resultTitle').innerHTML=win?'The ford is safe<span>Chapter complete</span>':'The road grows dark<span>Company defeated</span>';$('resultText').textContent=win?'Grozny’s bandits scatter into the hills. The caravan is safe, and Lyn’s journey continues with a new purpose.':'Lyn’s company has fallen. Regroup and try another approach to the crossing.';$('result').classList.remove('hidden')}

